PRAGMA foreign_keys = ON;
CREATE TABLE IF NOT EXISTS projects (id TEXT PRIMARY KEY NOT NULL, title TEXT NOT NULL, description TEXT NOT NULL DEFAULT '', language TEXT NOT NULL, workflow_type TEXT NOT NULL DEFAULT 'AUDIO_STORY', status TEXT NOT NULL DEFAULT 'ACTIVE', render_config TEXT NOT NULL, row_version INTEGER NOT NULL DEFAULT 1, created_at TEXT NOT NULL, updated_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS chapters (id TEXT PRIMARY KEY NOT NULL, project_id TEXT NOT NULL REFERENCES projects(id) ON DELETE CASCADE, number INTEGER NOT NULL, title TEXT NOT NULL, content TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'ACTIVE', revision INTEGER NOT NULL DEFAULT 1, row_version INTEGER NOT NULL DEFAULT 1, created_at TEXT NOT NULL, updated_at TEXT NOT NULL, UNIQUE(project_id, number));
CREATE TABLE IF NOT EXISTS workflow_executions (id TEXT PRIMARY KEY NOT NULL, project_id TEXT NOT NULL REFERENCES projects(id) ON DELETE CASCADE, type TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'PENDING', cancellation_requested_at TEXT, created_at TEXT NOT NULL, updated_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS workflow_steps (id TEXT PRIMARY KEY NOT NULL, execution_id TEXT NOT NULL REFERENCES workflow_executions(id) ON DELETE CASCADE, step_key TEXT NOT NULL, type TEXT NOT NULL, entity_id TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'PENDING', input_fingerprint TEXT NOT NULL, progress REAL NOT NULL DEFAULT 0, progress_message TEXT NOT NULL DEFAULT '', attempts INTEGER NOT NULL DEFAULT 0, max_attempts INTEGER NOT NULL DEFAULT 3, next_attempt_at TEXT, lease_owner TEXT, lease_expires_at TEXT, current_attempt_id TEXT, cancellation_requested_at TEXT, error TEXT, created_at TEXT NOT NULL, updated_at TEXT NOT NULL, UNIQUE(execution_id, step_key));
CREATE INDEX IF NOT EXISTS workflow_steps_claim_idx ON workflow_steps(status, next_attempt_at, created_at);
CREATE TABLE IF NOT EXISTS workflow_step_dependencies (step_id TEXT NOT NULL REFERENCES workflow_steps(id) ON DELETE CASCADE, depends_on_step_id TEXT NOT NULL REFERENCES workflow_steps(id) ON DELETE CASCADE, required INTEGER NOT NULL DEFAULT 1, PRIMARY KEY(step_id, depends_on_step_id));
CREATE TABLE IF NOT EXISTS workflow_step_attempts (id TEXT PRIMARY KEY NOT NULL, step_id TEXT NOT NULL REFERENCES workflow_steps(id) ON DELETE CASCADE, attempt_number INTEGER NOT NULL, worker_id TEXT NOT NULL, status TEXT NOT NULL, started_at TEXT NOT NULL, heartbeat_at TEXT, finished_at TEXT, error TEXT, checkpoint TEXT, UNIQUE(step_id, attempt_number));
CREATE TABLE IF NOT EXISTS jobs (id TEXT PRIMARY KEY NOT NULL, type TEXT NOT NULL, entity_id TEXT NOT NULL, step_id TEXT NOT NULL REFERENCES workflow_steps(id) ON DELETE CASCADE, status TEXT NOT NULL DEFAULT 'PENDING', progress REAL NOT NULL DEFAULT 0, error TEXT, attempts INTEGER NOT NULL DEFAULT 0, created_at TEXT NOT NULL, started_at TEXT, completed_at TEXT);
CREATE TABLE IF NOT EXISTS assets (id TEXT PRIMARY KEY NOT NULL, project_id TEXT NOT NULL REFERENCES projects(id) ON DELETE CASCADE, type TEXT NOT NULL, role TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'READY', path TEXT NOT NULL UNIQUE, media_type TEXT NOT NULL, bytes INTEGER NOT NULL, sha256 TEXT NOT NULL, source_entity_id TEXT, source_step_id TEXT, input_fingerprint TEXT, metadata TEXT NOT NULL DEFAULT '{}', is_current INTEGER NOT NULL DEFAULT 0, validation_error TEXT, created_at TEXT NOT NULL, updated_at TEXT NOT NULL);
CREATE INDEX IF NOT EXISTS assets_current_role_idx ON assets(project_id, role, is_current);
CREATE INDEX IF NOT EXISTS assets_project_type_idx ON assets(project_id, type);
CREATE TABLE IF NOT EXISTS asset_dependencies (asset_id TEXT NOT NULL REFERENCES assets(id) ON DELETE CASCADE, depends_on_asset_id TEXT NOT NULL REFERENCES assets(id) ON DELETE CASCADE, role TEXT NOT NULL, source_hash TEXT NOT NULL, PRIMARY KEY(asset_id, depends_on_asset_id));
CREATE TABLE IF NOT EXISTS tts_segments (id TEXT PRIMARY KEY NOT NULL, chapter_id TEXT NOT NULL REFERENCES chapters(id) ON DELETE CASCADE, segment_index INTEGER NOT NULL, text TEXT NOT NULL, text_hash TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'PENDING', audio_asset_id TEXT REFERENCES assets(id), duration_ms INTEGER, attempts INTEGER NOT NULL DEFAULT 0, error TEXT, fingerprint TEXT NOT NULL, UNIQUE(chapter_id, segment_index));
CREATE TABLE IF NOT EXISTS worker_heartbeats (worker_id TEXT PRIMARY KEY NOT NULL, last_seen_at TEXT NOT NULL, status TEXT NOT NULL, version TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS render_jobs (id TEXT PRIMARY KEY NOT NULL, project_id TEXT NOT NULL REFERENCES projects(id) ON DELETE CASCADE, step_id TEXT NOT NULL REFERENCES workflow_steps(id) ON DELETE CASCADE, timeline_asset_id TEXT REFERENCES assets(id), output_asset_id TEXT REFERENCES assets(id), expected_duration_ms INTEGER, actual_duration_ms INTEGER, status TEXT NOT NULL DEFAULT 'PENDING', created_at TEXT NOT NULL, updated_at TEXT NOT NULL);
